BLOCKED = {
    "2026_bahrain":
        "Externe koppeling geblokkeerd: de provider noemt Malaysia/Kuala Lumpur, "
        "maar geeft Bahrain als land. Aanvullend bewijs voor de venue-koppeling "
        "is nodig. Projectwaarden worden niet gewijzigd."
}

def get_context_mapping(event_key, circuit, layout):
    if event_key in BLOCKED:
        return None, BLOCKED[event_key]
    mapping = MAPPINGS.get(event_key)
    if mapping is None:
        return None, (
            "Voor dit event bestaat nog geen gecontroleerde externe "
            "sessiekoppeling. Er wordt geen OpenF1-aanvraag uitgevoerd."
        )
    if (
        str(circuit or "").strip() != mapping["project_circuit"]
        or str(layout or "").strip() != mapping["project_layout"]
    ):
        return None, (
            "Circuit of layout is veranderd sinds de mappingreview. "
            "Ophalen blijft geblokkeerd totdat de koppeling opnieuw is beoordeeld."
        )
    return copy.deepcopy(mapping), None
